bool is_valid_subdomain(const std::string& target_domain, const std::string& domain) {
    // Check if target_domain is a valid subdomain of the given domain
    std::regex domain_regex("^" + std::regex_replace(domain, std::regex("\\."), "\\\\.") + "$");
    return std::regex_match(target_domain, domain_regex);
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_valid_subdomain("music.example.com", "example.com") << std::endl;      // true
